'use strict';
/* Generates prisma/schema.postgres.prisma from prisma/schema.prisma for
 * production (Vercel + Neon). The only differences are:
 *   - datasource provider : sqlite  ->  postgresql
 *   - generator client    : adds the Vercel/Lambda engine target
 *
 * The schema is deliberately portable (no native enums, no Json/array columns),
 * so this is a lossless text transformation. The generated file is git-ignored
 * and rebuilt on every production build (see vercel.json) and by the
 * `db:push:prod` / `prisma:gen:prod` scripts.
 *
 *   node scripts/prepare-prod-schema.js
 */
const fs = require('fs');
const path = require('path');

const srcPath = path.join(__dirname, '..', 'prisma', 'schema.prisma');
const outPath = path.join(__dirname, '..', 'prisma', 'schema.postgres.prisma');

let schema = fs.readFileSync(srcPath, 'utf8');

if (!/provider\s*=\s*"sqlite"/.test(schema)) {
  throw new Error(
    'prepare-prod-schema: expected `provider = "sqlite"` in prisma/schema.prisma'
  );
}

schema = schema.replace(
  /provider\s*=\s*"sqlite"[^\n]*/,
  'provider = "postgresql" // generated for production (Vercel + Neon)'
);

schema = schema.replace(
  /(generator\s+client\s*\{)/,
  '$1\n  // Engine binary for the Vercel Node runtime (Amazon Linux 2023).\n  binaryTargets = ["native", "rhel-openssl-3.0.x"]'
);

const banner =
  '// AUTO-GENERATED by scripts/prepare-prod-schema.js — DO NOT EDIT.\n' +
  '// Source of truth: prisma/schema.prisma\n\n';

fs.writeFileSync(outPath, banner + schema);
console.log('wrote ' + path.relative(process.cwd(), outPath));
